$base = "http://zentao-biz.zhi.com"
$body = @{ account='tiany'; password='Field123456' } | ConvertTo-Json
try {
  $r = Invoke-WebRequest -Uri "$base/api.php/v1/tokens" -Method Post -Body $body -ContentType 'application/json' -UseBasicParsing
  $tok = ($r.Content | ConvertFrom-Json).token
  Write-Output "TOKEN_OK:$tok"
  $hd = @{ 'Token' = $tok; 'Accept' = 'application/json' }
  foreach ($fid in 21331,21431) {
    try {
      $fr = Invoke-WebRequest -Uri "$base/api.php/v1/files/$fid" -Headers $hd -UseBasicParsing
      $bytes = $fr.RawContentStream.ToArray()
      $out = "D:\repository\苏州市房地产监测V3\bug6112_$fid.png"
      [IO.File]::WriteAllBytes($out, $bytes)
      Write-Output "SAVED:$out size=$($bytes.Length) head=$($bytes[0]),$($bytes[1])"
    } catch { Write-Output "FILE_FAIL $fid : $($_.Exception.Message)" }
  }
} catch { Write-Output "TOKEN_FAIL: $($_.Exception.Message)" }

